from pathlib import Path

p=Path('client/src/pages/Admin.tsx'); s=p.read_text()
anchor='function Field({ label, value, onChange, placeholder, multiline = false, error, onBlur, advanced = false }: { label: string; value: string | number; onChange: (value: string) => void; placeholder?: string; multiline?: boolean; error?: string; onBlur?: () => void; advanced?: boolean }) { return <label className={`admin-field ${advanced ? "advanced-field" : ""} ${error ? "has-error" : ""}`}><span>{label}</span>{multiline ? <textarea value={value} onChange={(event) => onChange(event.target.value)} onBlur={onBlur} placeholder={placeholder} rows={3} /> : <input value={value} onChange={(event) => onChange(event.target.value)} onBlur={onBlur} placeholder={placeholder} />}{error && <small className="field-error"><AlertCircle size={12} /> {error}</small>}</label>; }'
component='''\nfunction WarrantyDocumentPreview({ url, name, mime, label }: { url?: string | null; name?: string | null; mime?: string | null; label: string }) {\n  if (!url) return null;\n  const isImage = mime?.startsWith("image/") || /\\.(jpe?g|png|webp|gif)$/i.test(name ?? "");\n  return <div className="warranty-document-preview">{isImage ? <a className="warranty-thumbnail-link" href={url} target="_blank" rel="noreferrer" aria-label={`Abrir ${label}: ${name || "imagem"}`}><img className="warranty-thumbnail" src={url} alt={`${label} — ${name || "imagem anexada"}`} loading="lazy" /></a> : <a className="warranty-pdf-preview" href={url} target="_blank" rel="noreferrer" aria-label={`Abrir ${label}: ${name || "documento PDF"}`}><FileText size={22} /><span>PDF</span></a>}<a className="warranty-document-link" href={url} target="_blank" rel="noreferrer"><FileText size={13} /> {label}</a></div>;\n}\n'''
if anchor not in s: raise SystemExit('Field anchor not found')
s=s.replace(anchor, anchor+component)
old='''<label className="warranty-upload-button" htmlFor={`warranty-document-${record.id}`}><Camera size={14} /> {record.signedDocumentUrl ? "Trocar termo 1" : "Fotografar termo 1"}</label>{record.signedDocumentUrl && <a className="warranty-document-link" href={record.signedDocumentUrl} target="_blank" rel="noreferrer"><FileText size={13} /> Ver termo 1</a>}<input id={`warranty-document-2-${record.id}`} type="file" accept="application/pdf,image/jpeg,image/png,image/webp" capture="environment" hidden onChange={(event) => void attachWarrantyDocument(event, record.id, 2)} /><label className="warranty-upload-button" htmlFor={`warranty-document-2-${record.id}`}><Camera size={14} /> {record.signedDocument2Url ? "Trocar termo 2" : "Fotografar termo 2"}</label>{record.signedDocument2Url && <a className="warranty-document-link" href={record.signedDocument2Url} target="_blank" rel="noreferrer"><FileText size={13} /> Ver termo 2</a>}'''
new='''<label className="warranty-upload-button" htmlFor={`warranty-document-${record.id}`}><Camera size={14} /> {record.signedDocumentUrl ? "Trocar termo 1" : "Fotografar termo 1"}</label><WarrantyDocumentPreview url={record.signedDocumentUrl} name={record.signedDocumentName} mime={record.signedDocumentMime} label="Ver termo 1" /><input id={`warranty-document-2-${record.id}`} type="file" accept="application/pdf,image/jpeg,image/png,image/webp" capture="environment" hidden onChange={(event) => void attachWarrantyDocument(event, record.id, 2)} /><label className="warranty-upload-button" htmlFor={`warranty-document-2-${record.id}`}><Camera size={14} /> {record.signedDocument2Url ? "Trocar termo 2" : "Fotografar termo 2"}</label><WarrantyDocumentPreview url={record.signedDocument2Url} name={record.signedDocument2Name} mime={record.signedDocument2Mime} label="Ver termo 2" />'''
if old not in s: raise SystemExit('document action block not found')
s=s.replace(old,new)
p.write_text(s)

p=Path('client/src/index.css'); s=p.read_text()
css='''\n/* Warranty thumbnails: quick visual confirmation before opening the private document. */\n.warranty-document-preview { display: inline-flex; align-items: center; gap: 8px; min-height: 48px; }\n.warranty-thumbnail-link, .warranty-pdf-preview { display: grid; place-items: center; flex: 0 0 56px; width: 56px; height: 48px; overflow: hidden; border: 1px solid rgba(29,184,255,.38); border-radius: 9px; background: rgba(224,242,254,.12); color: #7dd3fc; transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease; }\n.warranty-thumbnail-link:hover, .warranty-thumbnail-link:focus-visible, .warranty-pdf-preview:hover, .warranty-pdf-preview:focus-visible { border-color: #1db8ff; box-shadow: 0 0 0 3px rgba(29,184,255,.16); transform: translateY(-1px); }\n.warranty-thumbnail { display: block; width: 100%; height: 100%; object-fit: cover; }\n.warranty-pdf-preview { gap: 1px; font-size: .62rem; font-weight: 800; }\n.warranty-pdf-preview span { line-height: 1; }\n.warranty-document-preview .warranty-document-link { flex: 0 0 auto; }\n@media (max-width: 640px) {\n  .warranty-document-preview { width: 100%; justify-content: flex-start; }\n  .warranty-document-preview .warranty-document-link { flex: 1 1 auto; }\n}\n'''
p.write_text(s.rstrip()+"\n"+css)

p=Path('server/signed-warranty.test.ts'); s=p.read_text()
needle='expect(admin).toContain("documentSlot");'
if needle in s and 'warranty-thumbnail' not in s:
 s=s.replace(needle, needle+'\n    expect(admin).toContain("warranty-thumbnail");\n    expect(admin).toContain("warranty-pdf-preview");')
p.write_text(s)
